Here's a modern MSTest data-driven test class for your `PriceCalculator`:

```csharp
using Microsoft.VisualStudio.TestTools.UnitTesting;

[TestClass]
public sealed class PriceCalculatorTests
{
    private readonly PriceCalculator _calculator = new();

    // --- DataRow: inline values for simple cases ---

    [TestMethod]
    [DataRow(10.00, 1, 10.00, DisplayName = "Single item")]
    [DataRow(25.50, 3, 76.50, DisplayName = "Multiple items")]
    [DataRow(0.00, 5, 0.00, DisplayName = "Zero price")]
    [DataRow(99.99, 0, 0.00, DisplayName = "Zero quantity")]
    public void CalculateTotal_WithVariousInputs_ReturnsExpected(
        double price, int quantity, double expected)
    {
        var result = _calculator.CalculateTotal((decimal)price, quantity);

        Assert.AreEqual((decimal)expected, result);
    }

    // --- DynamicData with ValueTuples (preferred for complex/decimal data) ---

    [TestMethod]
    [DynamicData(nameof(DiscountTestData))]
    public void ApplyDiscount_WithVariousDiscounts_ReturnsExpected(
        decimal price, int discountPercent, decimal expected)
    {
        var result = _calculator.ApplyDiscount(price, discountPercent);

        Assert.AreEqual(expected, result);
    }

    public static IEnumerable<(decimal price, int discountPercent, decimal expected)> DiscountTestData =>
    [
        (100m, 10, 90m),
        (200m, 25, 150m),
        (50m, 0, 50m),
        (80m, 100, 0m),
        (0m, 50, 0m),
    ];

    // --- Edge case: invalid discount throws ---

    [TestMethod]
    [DataRow(-1)]
    [DataRow(101)]
    public void ApplyDiscount_InvalidPercent_Throws(int discountPercent)
    {
        var ex = Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => _calculator.ApplyDiscount(100m, discountPercent));

        Assert.AreEqual("discountPercent", ex.ParamName);
    }
}
```

**Key points:**

- **`[DataRow]`** — best for simple inline primitives (note: `decimal` literals aren't compile-time constants, so use `double` and cast, or switch to `DynamicData`)
- **`DynamicData` with ValueTuples** (MSTest 3.7+) — type-safe, supports `decimal` directly, scales to complex objects
- **`Assert.ThrowsExactly<T>`** — replaces `[ExpectedException]`
- **Sealed class**, AAA pattern, descriptive `DisplayName` values
- No need for `[DataTestMethod]` — `[TestMethod]` handles data rows in MSTest 3.x+
